object WaqiahData {
    val lines = listOf(
        DuaLine(2400L, "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "In the name of Allah, the Entirely Merciful, the Especially Merciful."),
        DuaLine(4800L, "إِذَا وَقَعَتِ ٱلۡوَاقِعَةُ", "1. When the Occurrence occurs"),
        DuaLine(9000L, "لَيۡسَ لِوَقۡعَتِهَا كَاذِبَةٌ", "2. There is, at its occurrence, no denial"),
        DuaLine(13799L, "خَافِضَةࣱ رَّافِعَةٌ", "3. It will bring down [some] and raise up [others]"),
        DuaLine(17900L, "إِذَا رُجَّتِ ٱلۡأَرۡضُ رَجࣰّا", "4. When the earth is shaken with convulsion"),
        DuaLine(23599L, "وَبُسَّتِ ٱلۡجِبَالُ بَسࣰّا", "5. And the mountains are broken down, crumbling"),
